-- InsightForge schema (generated by scripts/export_schema.py from insightforge/schema.py)

CREATE TABLE audit_log (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	workspace_id INTEGER, 
	user_id INTEGER, 
	action VARCHAR(60) NOT NULL, 
	detail TEXT, 
	created_at DATETIME NOT NULL DEFAULT (now()), 
	PRIMARY KEY (id)
);

CREATE TABLE workspaces (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(120) NOT NULL, 
	industry VARCHAR(60) NOT NULL, 
	country VARCHAR(60) NOT NULL DEFAULT 'Ghana', 
	objective TEXT, 
	active_use_case VARCHAR(80), 
	created_at DATETIME NOT NULL DEFAULT (now()), 
	PRIMARY KEY (id)
);

CREATE TABLE customers (
	row_id INTEGER NOT NULL AUTO_INCREMENT, 
	workspace_id INTEGER NOT NULL, 
	customer_id VARCHAR(12) NOT NULL, 
	full_name VARCHAR(120), 
	phone VARCHAR(20), 
	email VARCHAR(160), 
	gender VARCHAR(10), 
	date_of_birth DATE, 
	region VARCHAR(40), 
	city VARCHAR(60), 
	segment VARCHAR(20), 
	acquisition_channel VARCHAR(30), 
	signup_date DATE NOT NULL, 
	PRIMARY KEY (row_id), 
	CONSTRAINT uq_customers_ws_cust UNIQUE (workspace_id, customer_id), 
	FOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE
);

CREATE INDEX ix_customers_phone ON customers (workspace_id, phone);

CREATE TABLE datasets (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	workspace_id INTEGER NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	source VARCHAR(40) NOT NULL, 
	table_name VARCHAR(80), 
	seed INTEGER, 
	as_of_date DATE, 
	row_counts TEXT, 
	status VARCHAR(20) NOT NULL DEFAULT 'ready', 
	created_at DATETIME NOT NULL DEFAULT (now()), 
	PRIMARY KEY (id), 
	FOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE
);

CREATE TABLE plans (
	workspace_id INTEGER NOT NULL, 
	plan_id VARCHAR(10) NOT NULL, 
	plan_name VARCHAR(60) NOT NULL, 
	plan_type VARCHAR(20) NOT NULL, 
	monthly_fee FLOAT NOT NULL, 
	data_gb FLOAT NOT NULL, 
	PRIMARY KEY (workspace_id, plan_id), 
	FOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE
);

CREATE TABLE users (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	workspace_id INTEGER NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	full_name VARCHAR(120) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	`role` VARCHAR(20) NOT NULL DEFAULT 'owner', 
	created_at DATETIME NOT NULL DEFAULT (now()), 
	PRIMARY KEY (id), 
	FOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE, 
	UNIQUE (email)
);

CREATE TABLE model_runs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	workspace_id INTEGER NOT NULL, 
	dataset_id INTEGER NOT NULL, 
	use_case_id VARCHAR(80) NOT NULL, 
	task_type VARCHAR(20) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	best_model VARCHAR(60), 
	metrics LONGTEXT, 
	details LONGTEXT, 
	artifact_path VARCHAR(255), 
	score_snapshot DATE, 
	created_by INTEGER, 
	created_at DATETIME NOT NULL DEFAULT (now()), 
	PRIMARY KEY (id), 
	FOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE, 
	FOREIGN KEY(dataset_id) REFERENCES datasets (id) ON DELETE CASCADE, 
	FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE TABLE subscriptions (
	row_id INTEGER NOT NULL AUTO_INCREMENT, 
	workspace_id INTEGER NOT NULL, 
	subscription_id VARCHAR(14) NOT NULL, 
	customer_id VARCHAR(12) NOT NULL, 
	plan_id VARCHAR(10) NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE, 
	status VARCHAR(12) NOT NULL, 
	contract_type VARCHAR(20) NOT NULL, 
	autopay BOOL NOT NULL, 
	cancel_reason VARCHAR(40), 
	PRIMARY KEY (row_id), 
	CONSTRAINT uq_subs_ws_sub UNIQUE (workspace_id, subscription_id), 
	FOREIGN KEY(workspace_id, customer_id) REFERENCES customers (workspace_id, customer_id) ON DELETE CASCADE, 
	FOREIGN KEY(workspace_id, plan_id) REFERENCES plans (workspace_id, plan_id) ON DELETE CASCADE
);

CREATE INDEX ix_subs_customer ON subscriptions (workspace_id, customer_id);

CREATE TABLE support_tickets (
	row_id INTEGER NOT NULL AUTO_INCREMENT, 
	workspace_id INTEGER NOT NULL, 
	ticket_id VARCHAR(16) NOT NULL, 
	customer_id VARCHAR(12) NOT NULL, 
	opened_date DATE NOT NULL, 
	category VARCHAR(20) NOT NULL, 
	resolution_hours FLOAT, 
	csat_score INTEGER, 
	PRIMARY KEY (row_id), 
	FOREIGN KEY(workspace_id, customer_id) REFERENCES customers (workspace_id, customer_id) ON DELETE CASCADE
);

CREATE INDEX ix_tickets_customer ON support_tickets (workspace_id, customer_id, opened_date);

CREATE TABLE ai_outputs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	workspace_id INTEGER NOT NULL, 
	run_id INTEGER, 
	task VARCHAR(40) NOT NULL, 
	provider VARCHAR(20) NOT NULL, 
	prompt_hash VARCHAR(64) NOT NULL, 
	context_json LONGTEXT NOT NULL, 
	question TEXT, 
	output_text LONGTEXT, 
	validation TEXT, 
	status VARCHAR(20) NOT NULL, 
	latency_ms INTEGER, 
	created_by INTEGER, 
	created_at DATETIME NOT NULL DEFAULT (now()), 
	PRIMARY KEY (id), 
	FOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE, 
	FOREIGN KEY(run_id) REFERENCES model_runs (id) ON DELETE SET NULL, 
	FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE TABLE monthly_usage (
	row_id INTEGER NOT NULL AUTO_INCREMENT, 
	workspace_id INTEGER NOT NULL, 
	usage_id VARCHAR(16) NOT NULL, 
	subscription_id VARCHAR(14) NOT NULL, 
	usage_month DATE NOT NULL, 
	data_gb_used FLOAT, 
	voice_minutes FLOAT, 
	sms_count INTEGER, 
	dropped_calls INTEGER, 
	PRIMARY KEY (row_id), 
	FOREIGN KEY(workspace_id, subscription_id) REFERENCES subscriptions (workspace_id, subscription_id) ON DELETE CASCADE
);

CREATE INDEX ix_usage_sub_month ON monthly_usage (workspace_id, subscription_id, usage_month);

CREATE TABLE payments (
	row_id INTEGER NOT NULL AUTO_INCREMENT, 
	workspace_id INTEGER NOT NULL, 
	payment_id VARCHAR(16) NOT NULL, 
	subscription_id VARCHAR(14) NOT NULL, 
	billing_month DATE NOT NULL, 
	due_date DATE NOT NULL, 
	amount_due FLOAT NOT NULL, 
	amount_paid FLOAT, 
	paid_date DATE, 
	payment_method VARCHAR(20), 
	PRIMARY KEY (row_id), 
	FOREIGN KEY(workspace_id, subscription_id) REFERENCES subscriptions (workspace_id, subscription_id) ON DELETE CASCADE
);

CREATE INDEX ix_payments_sub_month ON payments (workspace_id, subscription_id, billing_month);

CREATE TABLE predictions (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	run_id INTEGER NOT NULL, 
	workspace_id INTEGER NOT NULL, 
	entity_id VARCHAR(40) NOT NULL, 
	score FLOAT NOT NULL, 
	risk_tier VARCHAR(10) NOT NULL, 
	value FLOAT, 
	top_reasons TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(run_id) REFERENCES model_runs (id) ON DELETE CASCADE
);

CREATE INDEX ix_predictions_run ON predictions (run_id, risk_tier);

-- =====================================================================
-- Silver layer: cleaned, de-duplicated, PII-minimised views over the raw
-- tables. Portable across MySQL 8 / MariaDB 10.2+ and SQLite 3.25+.
-- Statements are separated by a line holding a double semicolon.
-- =====================================================================

DROP VIEW IF EXISTS v_tickets_clean;
DROP VIEW IF EXISTS v_payments_clean;
DROP VIEW IF EXISTS v_usage_clean;
DROP VIEW IF EXISTS v_subscriptions_clean;
DROP VIEW IF EXISTS v_customers_clean;

-- Customers: one row per real person (duplicates share a phone number; keep the
-- earliest record), region labels standardised, PII columns (name, phone,
-- email) deliberately excluded so downstream analytics and the AI layer never
-- see them.
CREATE VIEW v_customers_clean AS
SELECT
    r.workspace_id,
    r.customer_id,
    r.gender,
    r.date_of_birth,
    r.segment,
    r.acquisition_channel,
    r.signup_date,
    CASE
        WHEN LOWER(TRIM(r.region)) IN ('greater accra', 'gt. accra', 'g. accra', 'accra') THEN 'Greater Accra'
        WHEN LOWER(TRIM(r.region)) IN ('ashanti', 'ashanti region', 'kumasi') THEN 'Ashanti'
        WHEN LOWER(TRIM(r.region)) = 'western' THEN 'Western'
        WHEN LOWER(TRIM(r.region)) = 'central' THEN 'Central'
        WHEN LOWER(TRIM(r.region)) = 'eastern' THEN 'Eastern'
        WHEN LOWER(TRIM(r.region)) = 'northern' THEN 'Northern'
        WHEN LOWER(TRIM(r.region)) = 'volta' THEN 'Volta'
        WHEN LOWER(TRIM(r.region)) = 'bono' THEN 'Bono'
        WHEN LOWER(TRIM(r.region)) = 'upper east' THEN 'Upper East'
        WHEN LOWER(TRIM(r.region)) = 'upper west' THEN 'Upper West'
        ELSE NULL
    END AS region
FROM (
    SELECT c.*,
           ROW_NUMBER() OVER (
               PARTITION BY c.workspace_id, COALESCE(c.phone, c.customer_id)
               ORDER BY c.signup_date, c.customer_id
           ) AS rn
    FROM customers c
) r
WHERE r.rn = 1;

-- Subscriptions: records whose end_date precedes start_date are quarantined
-- (excluded); status is re-derived from end_date because the raw status column
-- is not always kept in sync.
CREATE VIEW v_subscriptions_clean AS
SELECT
    s.workspace_id,
    s.subscription_id,
    s.customer_id,
    s.plan_id,
    s.start_date,
    s.end_date,
    CASE WHEN s.end_date IS NULL THEN 'active' ELSE 'cancelled' END AS status,
    s.contract_type,
    s.autopay,
    s.cancel_reason
FROM subscriptions s
WHERE s.end_date IS NULL OR s.end_date >= s.start_date;

-- Usage: one row per subscription-month (duplicates removed), negative and
-- physically implausible readings (> 5x the plan allowance) set to NULL.
CREATE VIEW v_usage_clean AS
SELECT
    d.workspace_id,
    d.subscription_id,
    d.usage_month,
    CASE
        WHEN d.data_gb_used < 0 THEN NULL
        WHEN d.data_gb_used > 5 * p.data_gb THEN NULL
        ELSE d.data_gb_used
    END AS data_gb_used,
    d.voice_minutes,
    d.sms_count,
    d.dropped_calls
FROM (
    SELECT u.*,
           ROW_NUMBER() OVER (
               PARTITION BY u.workspace_id, u.subscription_id, u.usage_month
               ORDER BY u.usage_id
           ) AS rn
    FROM monthly_usage u
) d
JOIN subscriptions s
  ON s.workspace_id = d.workspace_id AND s.subscription_id = d.subscription_id
JOIN plans p
  ON p.workspace_id = s.workspace_id AND p.plan_id = s.plan_id
WHERE d.rn = 1;

-- Payments: one bill per subscription-month (double-posted rows removed),
-- with late / unpaid flags and a data-consistency flag.
CREATE VIEW v_payments_clean AS
SELECT
    d.workspace_id,
    d.subscription_id,
    d.billing_month,
    d.due_date,
    d.amount_due,
    CASE WHEN d.amount_paid > 3 * d.amount_due THEN d.amount_due ELSE d.amount_paid END AS amount_paid,
    d.paid_date,
    d.payment_method,
    CASE WHEN d.paid_date IS NULL OR COALESCE(d.amount_paid, 0) = 0 THEN 1 ELSE 0 END AS is_unpaid,
    CASE WHEN d.paid_date IS NOT NULL AND d.paid_date > d.due_date THEN 1 ELSE 0 END AS is_late,
    CASE WHEN d.paid_date IS NOT NULL AND d.paid_date < d.billing_month THEN 1
         WHEN d.amount_paid > 3 * d.amount_due THEN 1
         ELSE 0 END AS has_inconsistency
FROM (
    SELECT p.*,
           ROW_NUMBER() OVER (
               PARTITION BY p.workspace_id, p.subscription_id, p.billing_month
               ORDER BY p.payment_id
           ) AS rn
    FROM payments p
) d
WHERE d.rn = 1;

-- Tickets: out-of-range CSAT (valid 1-5) and negative resolution times nulled.
CREATE VIEW v_tickets_clean AS
SELECT
    t.workspace_id,
    t.ticket_id,
    t.customer_id,
    t.opened_date,
    t.category,
    CASE WHEN t.resolution_hours < 0 THEN NULL ELSE t.resolution_hours END AS resolution_hours,
    CASE WHEN t.csat_score BETWEEN 1 AND 5 THEN t.csat_score ELSE NULL END AS csat_score
FROM support_tickets t;
